{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "ContextMenu",
    "displayName": "Context Menu",
    "group": "ContextMenu",
    "category": "Action",
    "isHiddenFromOverview": true,
    "keywords": [
      "contextmenu",
      "right-click",
      "menu",
      "popover",
      "actions",
      "context"
    ],
    "theming": {
      "targets": [
        {
          "className": "astryx-context-menu"
        }
      ],
      "vars": [
        {
          "name": "--_dropdown-menu-radius",
          "description": "Border radius of the menu popup",
          "default": "var(--radius-container)",
          "private": true
        },
        {
          "name": "--_dropdown-menu-padding",
          "description": "Inner padding of the menu popup",
          "default": "var(--spacing-1)",
          "private": true
        }
      ],
      "derived": [
        {
          "property": "borderRadius",
          "vars": [
            "--_dropdown-menu-radius"
          ]
        },
        {
          "property": "padding",
          "vars": [
            "--_dropdown-menu-padding"
          ]
        }
      ]
    },
    "description": "A context menu that appears on right-click at the cursor position. Wraps trigger content as children.",
    "props": [
      {
        "name": "children",
        "type": "ReactNode",
        "description": "The trigger area: right-click on this content to open the menu.",
        "required": true
      },
      {
        "name": "items",
        "type": "ContextMenuOption[]",
        "description": "Data-driven menu entries. Pass exactly one of `items` or `menuContent`. Each entry is one of: an action item `{label, onClick?, icon?, isDisabled?, variant?, items?}` (nested `items` open a flyout in popover presentation and drill into a new view in bottom-sheet presentation; variant `\"destructive\"` renders it in the error color), a divider `{type: \"divider\"}`, or a section `{type: \"section\", title?, items: [...action items]}`."
      },
      {
        "name": "menuContent",
        "type": "ReactNode",
        "description": "Custom JSX menu content for compound mode. Pass exactly one of `menuContent` or `items`."
      },
      {
        "name": "menuWidth",
        "type": "number | string",
        "description": "Custom menu width.",
        "default": "'160px'"
      },
      {
        "name": "size",
        "type": "'sm' | 'md' | 'lg'",
        "description": "Size of menu items: controls padding density.",
        "default": "'md'"
      },
      {
        "name": "label",
        "type": "string",
        "description": "Accessible name for the menu surface, announced when it opens.",
        "default": "'Context menu'"
      },
      {
        "name": "onOpenChange",
        "type": "(isOpen: boolean) => void",
        "description": "Callback fired when the menu opens or closes."
      },
      {
        "name": "presentation",
        "type": "'popover' | 'bottom-sheet' | 'adaptive'",
        "description": "Presentation policy. `popover` opens at the pointer position, `bottom-sheet` always uses an action sheet, and `adaptive` uses the BottomSheet on a compact touch screen: a coarse primary pointer, and a viewport narrower than the theme `md` breakpoint (768px by default) or shorter than 500px.",
        "default": "'popover'"
      },
      {
        "name": "isDisabled",
        "type": "boolean",
        "description": "When true, right-click shows the native browser context menu instead.",
        "default": "false"
      },
      {
        "name": "triggerXstyle",
        "type": "StyleXStyles | StyleXStyles[]",
        "description": "Styles applied to the trigger wrapper. Accepts `stylex.create()` values, not inline style objects."
      },
      {
        "name": "triggerAs",
        "type": "'div' | 'span'",
        "description": "The element the trigger wrapper renders as. 'div' is a block; 'span' an inline wrapper, so a reference inside prose can own a context menu without breaking the text flow.",
        "default": "'div'"
      }
    ],
    "components": [
      {
        "name": "ContextMenuItem"
      }
    ],
    "usage": {
      "anatomy": [
        {
          "name": "Trigger area",
          "required": true,
          "description": "Caller-provided region that accepts right-click, keyboard context-menu, and long-press input."
        },
        {
          "name": "Pointer menu surface",
          "required": false,
          "description": "Cursor-positioned menu panel used by the pointer presentation."
        },
        {
          "name": "Pointer action row",
          "required": false,
          "description": "DropdownMenu-owned action, selectable option, or submenu row in the pointer presentation."
        },
        {
          "name": "Touch sheet frame",
          "required": false,
          "description": "BottomSheet panel, content area, handle, and optional scrim that host touch actions."
        },
        {
          "name": "Touch menu surface",
          "required": false,
          "description": "ContextMenu-owned content panel rendered inside the touch sheet frame."
        },
        {
          "name": "Touch action list",
          "required": false,
          "description": "Spacious List that groups data-driven touch actions."
        },
        {
          "name": "Touch action row",
          "required": false,
          "description": "ListItem button used for a data-driven action or drill-in entry in the touch presentation."
        }
      ],
      "description": "A right-click context menu that appears at the cursor position. Use to provide contextual actions for specific elements or regions without cluttering the UI with visible buttons.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Keep menu items concise and action-oriented; users expect quick access to contextual actions."
        },
        {
          "guidance": true,
          "description": "Use sections and dividers to group related actions when the menu has many items."
        },
        {
          "guidance": true,
          "description": "Use `presentation=\"adaptive\"` when right-click should remain cursor-positioned on desktop while long-press opens a reachable BottomSheet on compact touch devices."
        },
        {
          "guidance": true,
          "description": "Ensure all context menu actions are also accessible via other UI elements for keyboard-only users."
        },
        {
          "guidance": true,
          "description": "Keep a visible MoreMenu or equivalent trigger for important mobile actions; long-press must not be the only route."
        },
        {
          "guidance": false,
          "description": "Use a ContextMenu as the only way to access important actions; not all users know to right-click."
        },
        {
          "guidance": false,
          "description": "Place more than 10–12 items in a single menu without grouping them into sections."
        }
      ]
    },
    "playground": {
      "defaults": {
        "children": {
          "__element": "Card",
          "props": {
            "padding": 6
          },
          "children": {
            "__element": "Text",
            "props": {
              "color": "secondary"
            },
            "children": "Right-click this area"
          }
        },
        "items": [
          {
            "label": "Edit"
          },
          {
            "label": "Duplicate"
          },
          {
            "type": "divider"
          },
          {
            "label": "Delete"
          }
        ]
      }
    },
    "package": "@astryxdesign/core",
    "import": "@astryxdesign/core/ContextMenu",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
